// The browser's projection of the scene description (04 §8.4; M2 step 4).
//
// It mirrors dipolar_app/scene.py line by line: a perspective camera looking from `position` at
// `target`, with a vertical field of view, near and far planes, and aspect = width / height.
// Screen pixels have x to the right and y down. `scripts/projection-parity.mjs` checks this module
// against the parity fixtures generated by the Python implementation (parity-fixtures.json), so
// the browser and the server-side SVG renderer place every object at the same pixel.

export type Vec3 = readonly [number, number, number];

export type Camera = {
  readonly position: Vec3;
  readonly target: Vec3;
  readonly up: Vec3;
  readonly fov_deg: number;
  readonly near: number;
  readonly far: number;
};

export type Projected = { readonly x: number; readonly y: number; readonly depth: number; readonly visible: boolean };

export const DEFAULT_FOV_DEG = 45;
export const FIT_MARGIN = 1.15;

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: Vec3, b: Vec3): number => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const unit = (a: Vec3): Vec3 => {
  const n = Math.sqrt(dot(a, a));
  if (!(n > 0)) throw new Error("a zero-length vector");
  return [a[0] / n, a[1] / n, a[2] / n];
};
const radians = (deg: number): number => (deg * Math.PI) / 180;

/** Each point as screen pixels (x right, y down), its depth along the view, and visibility. */
export function project(camera: Camera, width: number, height: number, points: readonly Vec3[]): Projected[] {
  const forward = unit(sub(camera.target, camera.position));
  const side = unit(cross(forward, camera.up));
  const up = cross(side, forward);
  const t = Math.tan(radians(camera.fov_deg) / 2);
  const aspect = width / height;
  if (!(t > 0 && Number.isFinite(t))) throw new Error("the field of view cannot project");
  return points.map((p) => {
    const v = sub(p, camera.position);
    const depth = dot(v, forward);
    // Clipped before any division, so a point inside the near plane never divides by ~0.
    if (!(camera.near <= depth && depth <= camera.far)) return { x: 0, y: 0, depth, visible: false };
    const ndcX = dot(v, side) / (depth * t * aspect);
    const ndcY = dot(v, up) / (depth * t);
    const x = ((ndcX + 1) / 2) * width;
    const y = ((1 - ndcY) / 2) * height;
    const visible = Math.abs(ndcX) <= 1 && Math.abs(ndcY) <= 1;
    return { x, y, depth, visible };
  });
}

/** Depths within this many Å tie (see DEPTH_QUANTUM in dipolar_app/scene.py). */
export const DEPTH_QUANTUM = 1e-9;
const depthKey = (depth: number): number => Math.floor(depth / DEPTH_QUANTUM + 0.5);

/** The visible IDs, far to near; depths within DEPTH_QUANTUM tie and go by ID (code-point order,
 * as Python sorts strings). */
export function drawOrder(ids: readonly string[], projected: readonly Projected[]): string[] {
  const keyed: [number, string][] = [];
  ids.forEach((id, k) => {
    const p = projected[k];
    if (p !== undefined && p.visible) keyed.push([-depthKey(p.depth), id]);
  });
  keyed.sort((a, b) => (a[0] !== b[0] ? a[0] - b[0] : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  return keyed.map(([, id]) => id);
}

/** A camera on +z of the points' centroid that fits their bounding sphere in the view. */
export function autoCamera(points: readonly Vec3[], width: number, height: number, fovDeg = DEFAULT_FOV_DEG): Camera {
  const n = points.length;
  if (n === 0) return { position: [0, 0, 10], target: [0, 0, 0], up: [0, 1, 0], fov_deg: fovDeg, near: 0.1, far: 100 };
  let sx = 0;
  let sy = 0;
  let sz = 0;
  for (const p of points) {
    sx += p[0];
    sy += p[1];
    sz += p[2];
  }
  const c: Vec3 = [sx / n, sy / n, sz / n];
  let radius = 0;
  for (const p of points) radius = Math.max(radius, Math.sqrt(dot(sub(p, c), sub(p, c))));
  radius = Math.max(radius, 1);
  const half = radians(fovDeg) / 2;
  const halfH = Math.atan(Math.tan(half) * Math.min(1, width / height));
  const distance = (FIT_MARGIN * radius) / Math.sin(halfH);
  return {
    position: [c[0], c[1], c[2] + distance],
    target: c,
    up: [0, 1, 0],
    fov_deg: fovDeg,
    near: Math.max(distance - 2 * radius, 0.01),
    far: distance + 2 * radius,
  };
}
